#[path="../../rust/crates/editor-api/src/mv_lut_atlas_layout.rs"]mod layout;
fn main(){let palettes:Vec<_>=std::env::args().skip(1).map(|arg|{let v:Vec<_>=arg.split('\t').collect();layout::Palette{id:v[0].into(),lut:v[1].into(),lut_duotone:v[2].into()}}).collect();match layout::layout(&palettes){Err(e)=>println!("error\t{e}"),Ok(plan)=>{for (alias,row) in &plan.aliases{println!("alias\t{alias}\t{row}");}for (index,row) in plan.rows.iter().enumerate(){match row{layout::Row::Image{path}=>println!("image\t{index}\t{path}"),layout::Row::Ramp{name,stops}=>println!("ramp\t{index}\t{name}\t{}",stops.iter().map(|(n,c)|format!("{n}:{c}")).collect::<Vec<_>>().join(";"))}}}}}
